// Packages/AstroCore/Tests/AstroCoreTests/CityGoldenTests.swift
//
// Golden values: Golden/cities.json, generated by Tools/golden/generate_golden.py with
// Skyfield + JPL DE421 using the USNO rise/set definitions (aa.usno.navy.mil/faq/RST_defs).
// Cities: Warsaw, Reykjavik, Tromsø (polar), Sydney, Quito, Honolulu, on the 2025 and 2026
// equinox/solstice dates (48 city-date pairs).
//
// Accuracy targets from the brief: rise/set ±1 min, azimuth/elevation ±0.1°, Moon illumination ±1%.

import Foundation
import Testing
@testable import AstroCore

struct CityGoldenTests {
    static let riseSetToleranceSeconds = 60.0
    static let angleToleranceDegrees = 0.1
    static let illuminationTolerance = 0.01

    /// Matches each expected time to the nearest computed one and checks counts agree.
    private func compare(
        _ expected: [String], _ actual: [AstroTime], _ label: String, _ stats: inout ErrorStats
    ) {
        #expect(expected.count == actual.count, "\(label): expected \(expected.count) events, got \(actual.count)")
        for e in expected {
            let et = Golden.time(e)
            guard let nearest = actual.min(by: { abs($0.ut - et.ut) < abs($1.ut - et.ut) }) else { continue }
            let err = abs(nearest.ut - et.ut) * 86_400
            stats.add(err, "\(label) \(e)")
            #expect(err <= Self.riseSetToleranceSeconds, "\(label) \(e): off by \(err) s")
        }
    }

    @Test func sunAndMoonRiseSet() {
        var sun = ErrorStats("Sun rise/set vs DE421 (USNO defs)", unit: "s")
        var moon = ErrorStats("Moon rise/set vs DE421 (USNO defs)", unit: "s")
        for row in Golden.cities.rows {
            let (start, end) = row.localDayWindow
            let label = "\(row.city) \(row.localDate)"
            let sunDay = Almanac.sunDay(observer: row.observer, from: start, to: end)
            compare(row.sunRise, sunDay.rises, "\(label) sunrise", &sun)
            compare(row.sunSet, sunDay.sets, "\(label) sunset", &sun)
            let moonDay = Almanac.moonDay(observer: row.observer, from: start, to: end)
            compare(row.moonRise, moonDay.rises, "\(label) moonrise", &moon)
            compare(row.moonSet, moonDay.sets, "\(label) moonset", &moon)
        }
        Report.line(sun)
        Report.line(moon)
        #expect(sun.count >= 70)
        #expect(moon.count >= 70)
    }

    @Test func twilights() {
        var stats = ErrorStats("Twilight -6/-12/-18 vs DE421", unit: "s")
        for row in Golden.cities.rows {
            let (start, end) = row.localDayWindow
            let label = "\(row.city) \(row.localDate)"
            for (kind, alt) in [("civil", -6.0), ("nautical", -12.0), ("astronomical", -18.0)] {
                guard let pair = row.twilight[kind] else { continue }
                let events = Almanac.altitudeCrossings(.sun, observer: row.observer, altitude: alt, from: start, to: end)
                compare(pair.dawn, events.filter { $0.direction == .rise }.map(\.time), "\(label) \(kind) dawn", &stats)
                compare(pair.dusk, events.filter { $0.direction == .set }.map(\.time), "\(label) \(kind) dusk", &stats)
            }
        }
        Report.line(stats)
    }

    @Test func azimuthElevation() {
        var az = ErrorStats("Azimuth (alt > -10) vs DE421", unit: "deg")
        var airless = ErrorStats("Elevation airless vs DE421", unit: "deg")
        var refracted = ErrorStats("Elevation refracted (alt > 5) vs DE421", unit: "deg")
        var illum = ErrorStats("Moon illuminated fraction vs DE421", unit: "")
        for row in Golden.cities.rows {
            for s in row.samples {
                let t = Golden.time(s.utc)
                let label = "\(row.city) \(s.body) \(s.utc)"
                if s.body == "moonIllumination", let f = s.fraction {
                    let err = abs(Lunar.illumination(at: t).fraction - f)
                    illum.add(err, label)
                    #expect(err <= Self.illuminationTolerance, "\(label): illumination off by \(err)")
                    continue
                }
                guard let body = Body(rawValue: s.body), let expAz = s.azimuth,
                      let expAlt = s.altitudeAirless, let expRefr = s.altitudeRefracted else { continue }
                let geo = Ephemeris.horizontal(body, at: t, observer: row.observer, refraction: .none)
                let altErr = abs(geo.altitude - expAlt)
                airless.add(altErr, label)
                #expect(altErr <= Self.angleToleranceDegrees, "\(label): elevation off by \(altErr)°")
                // Azimuth is ill-conditioned near the zenith; skip within 1° of it.
                if expAlt > -10, expAlt < 89 {
                    let azErr = angleDiff(geo.azimuth, expAz)
                    az.add(azErr, label)
                    #expect(azErr <= Self.angleToleranceDegrees, "\(label): azimuth off by \(azErr)°")
                }
                // Refraction models differ near the horizon (Saemundsson vs Bennett), compare above 5°.
                if expRefr > 5 {
                    let app = Ephemeris.horizontal(body, at: t, observer: row.observer, refraction: .normal)
                    let err = abs(app.altitude - expRefr)
                    refracted.add(err, label)
                    #expect(err <= Self.angleToleranceDegrees, "\(label): refracted elevation off by \(err)°")
                }
            }
        }
        Report.line(az)
        Report.line(airless)
        Report.line(refracted)
        Report.line(illum)
    }

    // Edge case: Tromsø (69.6° N) has midnight sun at the June solstice and polar night in December.
    @Test func tromsoPolarDayAndNight() {
        for row in Golden.cities.rows where row.city == "Tromso" {
            let (start, end) = row.localDayWindow
            let day = Almanac.sunDay(observer: row.observer, from: start, to: end)
            if row.localDate.hasSuffix("-06-21") {
                #expect(day.state == .alwaysAbove)
                #expect(abs(day.daylightDays - (end.ut - start.ut)) < 1e-9)
            } else if row.localDate.hasSuffix("-12-21") {
                #expect(day.state == .alwaysBelow)
                #expect(day.daylightDays == 0)
                // Civil twilight still happens around noon in Tromsø in December (Sun reaches ≈ −3°).
                #expect(day.civil.dawn.count == 1 && day.civil.dusk.count == 1)
            } else {
                #expect(day.state == .normal)
            }
        }
    }
}
